<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,watch,computed,nextTick} from 'vue';
import {post,safeOfficialUrl,safeArticleUrl} from '../api/client';
import AiAnalysis from './AiAnalysis.vue';
import MacroHistory from './MacroHistory.vue';
import MacroChanges from './MacroChanges.vue';
type Row=Record<string,any>;
const macroChangesAvailable=['5179','5180'].includes(location.port);
const props=defineProps<{token:string;mode:string}>();
const notificationStatus=ref<Row>({});
const items=ref<Row[]>([]),entities=ref<Row[]>([]),relations=ref<Row[]>([]),macro=ref<Row>({}),detail=ref<Row>(),page=ref(0),total=ref(0),topic=ref(''),series=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const proof=ref<Row>(),proofSection=ref<HTMLElement>(),detailSection=ref<HTMLElement>();
async function showProof(id:string){try{proof.value=await post<Row>('/research/proof/'+id,props.token);await nextTick();proofSection.value?.scrollIntoView({block:'start'});}catch(e){error.value=(e as Error).message}}
const linkEvidence=ref(''),reason=ref(''),quote=ref(''),relationTarget=ref(''),subject=ref(''),object=ref(''),relationType=ref('TRANSMISSION');
const time=beijingTime;
const state=(v:string)=>({PENDING:'待审核',VERIFIED:'已核实（人工审核）',CONFLICT:'存在冲突',EXPIRED:'已失效',REJECTED:'已否决',LINK_OFFICIAL_EVIDENCE:'关联官方证据'}[v]||v);
function json(value:any):any{if(value?.value)value=value.value;if(typeof value==='string'){try{return JSON.parse(value)}catch{return value}}return value;}
async function load(){busy.value=true;error.value='';try{if(props.mode==='全球宏观监测'){macro.value=await post<Row>('/research/macro',props.token,{series:series.value,page:page.value});if(!series.value&&macro.value.series?.length){series.value=macro.value.series[0].id;macro.value=await post('/research/macro',props.token,{series:series.value,page:0});}}else{const result=await post<{items:Row[];total:number}>('/research/candidates',props.token,{page:page.value,topic:topic.value,officialOnly:props.mode==='全球重要事件'});if(props.mode==='全球重要事件')notificationStatus.value=await post<Row>('/notifications/status',props.token);items.value=result.items;total.value=result.total;[entities.value,relations.value]=await Promise.all([post<Row[]>('/research/entities',props.token,{page:0}),post<Row[]>('/research/relations',props.token)]);}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(()=>props.mode,()=>{page.value=0;detail.value=undefined;load()},{immediate:true});
async function open(id:string){relationTarget.value='';try{detail.value=await post<Row>('/research/events/'+id,props.token);notice.value='';await nextTick();detailSection.value?.scrollIntoView({block:'start'});}catch(e){error.value=(e as Error).message}}
async function action(path:string,body:any){busy.value=true;error.value='';try{const result=await post<Row>(path,props.token,body);notice.value=result.message||'研究批次已处理 '+result.processed+' 条';await load();if(detail.value)await open(detail.value.event.id);}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const observations=computed<Row[]>(()=>[...(macro.value.observations||[])].sort((a,b)=>a.observation_date.localeCompare(b.observation_date)));
const actual=computed(()=>observations.value.filter(o=>o.value!=null&&Number.isFinite(Number(o.value))));
const range=computed(()=>{const values=actual.value.map(o=>Number(o.value));return {min:Math.min(...values),max:Math.max(...values)}});
const points=computed(()=>{const {min,max}=range.value;return actual.value.map((o,i)=>`${40+(Date.parse(o.observation_date)-Date.parse(actual.value[0].observation_date))*700/Math.max(1,Date.parse(actual.value[actual.value.length-1].observation_date)-Date.parse(actual.value[0].observation_date))},${180-(Number(o.value)-min)*140/(max-min||1)}`).join(' ')});
const selected=computed(()=>macro.value.series?.find((s:Row)=>s.id===series.value));
const policyName=(id:string)=>id.includes('.DFR.')?'存款便利利率':id.includes('.MRR_FR.')?'主要再融资固定利率':'边际贷款便利利率';
const frequency=(s:Row)=>s.frequency==='D'?'日度':s.frequency==='B'?'工作日频率（本序列仅公布利率变更日）':s.frequency;
const units=(s:Row)=>s.units==='PCPA'?'年化百分比（PCPA）':s.units+' / '+s.currency_denominator;
</script>
<template>
<section class="panel feed research"><p v-if="mode==='全球重要事件'">合格重大提醒 {{notificationStatus.classes?.filter((x:Row)=>x.message_class==='IMPORTANT_ALERT').reduce((n:number,x:Row)=>n+Number(x.important_eligible),0)??0}} 条。下列为官方消息研究候选，规则评分不代表重大告警或独立核实；聚合线索请在待核队列查看。</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice">{{notice}}</p>
 <template v-if="mode==='全球宏观监测'"><MacroChanges v-if="macroChangesAvailable" :token="token"/><p v-else>宏观变化分析已在本轮独立研究入口提供：<a href="http://127.0.0.1:5179/#/macro">打开宏观变化工作台</a></p><details :open="!macroChangesAvailable"><summary>既有采集与研究接口</summary><h2>官方经济指标</h2><p>欧洲央行参考汇率与官方政策利率 · 来源：欧洲央行。官方数据可在源站免费获取。</p><p>实时交易行情：未接入。观测日期不代表新闻发布时间，采集时间不代表可成交报价。</p><div class="filters"><select v-model="series" aria-label="官方指标序列" @change="page=0;load()"><option v-for="s in macro.series||[]" :key="s.id" :value="s.id">{{indicator(s.id)||'中文指标名称待核验'}}（{{frequency(s)}}）</option></select><button :disabled="busy" @click="load">刷新实际观测</button></div>
 <div v-if="!observations.length" class="empty">暂无真实数据</div><template v-else><h3>{{indicator(selected?.id)||'中文指标名称待核验'}}</h3><details><summary>查看官方指标原名</summary><p>{{selected?.title}}</p></details><p v-if="selected?.flow==='EXR'">每 1 欧元对应的外币数量；日度官方参考汇率。</p><p v-else>官方政策利率原始变更日序列；不填充未公布日期，也不据此补造每日观测。</p><p>原始单位 {{selected?units(selected):'未提供'}} · 发布频率：{{selected?frequency(selected):'未提供'}} · 最新观测日期 {{observations[observations.length-1]?.observation_date}} · 实际采集 <time :title="'UTC原值：'+utc(selected?.acquired_at)">{{time(selected?.acquired_at)}}</time></p>
 <svg v-if="actual.length>1" viewBox="0 0 800 230" role="img" aria-label="数据库真实参考汇率历史图" class="macro-chart"><path d="M40 20V190H760" fill="none" stroke="#516075"/><polyline :points="points" fill="none" stroke="#42c9b0" stroke-width="2"/><text x="42" y="215" fill="currentColor">{{actual[0]?.observation_date}}</text><text x="600" y="215" fill="currentColor">{{actual[actual.length-1]?.observation_date}}</text><text x="42" y="20" fill="currentColor">{{range.max}}</text><text x="42" y="185" fill="currentColor">{{range.min}}</text></svg>
 <details><summary>官方元数据与响应哈希</summary><pre>{{json(selected?.metadata)}}</pre><code>{{selected?.response_hash}}</code><p><a v-if="safeOfficialUrl(selected?.source_url||'')" :href="selected.source_url" target="_blank" rel="noopener noreferrer">查看官方原始响应 ↗</a></p></details>
 <article v-for="o in [...observations].reverse()" :key="o.evidence_id" :data-observation-id="o.evidence_id"><h3>{{o.observation_date}} · {{o.value==null?'缺失值':o.value}} {{selected?.units}}</h3><p>{{o.version>1?'官方响应数值或状态已变化，旧版本保留':'首次保存版本'}} · 版本 {{o.version}} · 实际采集 <time :title="'UTC原值：'+utc(o.collected_at)">{{time(o.collected_at)}}</time></p><code>SHA-256 {{o.raw_content_hash}}</code></article></template>
 <footer><button :disabled="page===0||busy" @click="page--;load()">上一页</button><span>第 {{page+1}} 页 · 每页最多 100 个观测</span><button :disabled="(macro.observations||[]).length<100||busy" @click="page++;load()">下一页</button></footer>
 <MacroHistory :token="token" :series-id="series"/></details>
 </template>
 <template v-else><h2>{{mode}}</h2><p>原始事实、文章组与研究判断分别记录。研究优先级不是消息真实性，也不是价格上涨概率。</p><div class="filters"><input v-model="topic" placeholder="筛选金融主题" aria-label="筛选金融主题"><button :disabled="busy" @click="page=0;load()">查询候选</button><button :disabled="busy" @click="action('/research/process',{limit:500,reprocess:false})">处理待治理批次</button><button :disabled="busy" @click="action('/research/process',{limit:500,reprocess:true})">按当前规则重处理历史</button></div>
 <div v-if="!items.length" class="empty">暂无真实数据</div><article v-for="r in items" :key="r.event_id" :data-candidate-id="r.event_id"><div class="meta"><span class="tag">{{sourceName(r.source_id,r.source_name)}}</span><span>{{r.level==='L2'?'聚合发现线索 · 待核验':'官方来源消息 · 来源确认'}} · 研究优先级 {{r.score}} · {{state(r.verification)}}</span></div><h3>{{displayTitle(r).text}}</h3><p class="muted">{{displayTitle(r).status}}</p><details><summary>查看官方原文标题</summary><p>{{r.original_title}}</p></details><p>实际发布时间 <time :title="'UTC原值：'+utc(r.published_at)">{{time(r.published_at,'官方发布时间未知')}}</time> · 首次发现 <time :title="'UTC原值：'+utc(r.first_seen_at)">{{time(r.first_seen_at)}}</time> · 采集 <time :title="'UTC原值：'+utc(r.collected_at)">{{time(r.collected_at)}}</time></p><p>主题：{{json(r.topics)?.join('、')||'尚未命中金融主题'}} · 同一原文文章组 {{r.article_group_size}} 条（原始记录全部保留）</p><div class="article-foot"><button @click="open(r.event_id)">查看事件研究</button><a v-if="safeOfficialUrl(r.source_url)" :href="r.source_url" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a><a v-if="r.level==='L2'&&safeArticleUrl(r.underlying_url||'')" :href="r.underlying_url" target="_blank" rel="noopener noreferrer">查看待核验原文 ↗</a></div></article>
 <footer><button :disabled="page===0||busy" @click="page--;load()">上一页</button><span>第 {{page+1}} 页 · 共 {{total}} 条</span><button :disabled="(page+1)*50>=total||busy" @click="page++;load()">下一页</button></footer>
 <template v-if="mode==='事件关联研究'||mode==='事件审核队列'"><h3>金融实体与机构索引</h3><p>同名聚合机构按各原始记录单独保留，身份未确认前不合并。证券代码仅在真实映射证据可用时显示。</p><article v-for="n in entities" :key="n.id"><strong>{{n.chinese_name||n.official_name}}</strong><p>{{n.status==='VERIFIED'?'官方证据确认实体名称':'机构名称候选，类型与身份待核验'}} · 证据 {{n.evidence_id}} · 有效期 <time :title="'UTC原值：'+utc(n.valid_from)">{{time(n.valid_from)}}</time> 至 <time :title="'UTC原值：'+utc(n.valid_until)">{{time(n.valid_until)}}</time></p><button @click="showProof(n.evidence_id)">查看实体证据</button></article><h3>企业与产业关系</h3><p v-if="!relations.length">暂无有证据的关系记录；产业链传导和市场验证尚未建立。</p><article v-for="r in relations" :key="r.id"><p>{{r.subject}} → {{r.object}} · {{state(r.status)}} · {{r.explanation}}</p><p>首次披露 <time :title="'UTC原值：'+utc(r.first_public_at)">{{time(r.first_public_at)}}</time> · 业务有效期 <time :title="'UTC原值：'+utc(r.effective_from)">{{time(r.effective_from)}}</time> 至 <time :title="'UTC原值：'+utc(r.effective_until)">{{time(r.effective_until)}}</time> · 证据 {{r.evidence_id||'尚未补充'}}</p><button v-if="r.evidence_id" @click="showProof(r.evidence_id)">查看关系证据</button><button @click="relationTarget=r.id">选择待审核关系</button></article>
 <template v-if="mode==='事件审核队列'"><h3>建立待审核关系</h3><div class="filters"><select v-model="subject" aria-label="关系主体"><option value="">选择主体</option><option v-for="n in entities" :value="n.id">{{n.chinese_name||n.official_name}}（{{n.id.slice(0,8)}}）</option></select><select v-model="object" aria-label="关系对象"><option value="">选择对象</option><option v-for="n in entities" :value="n.id">{{n.chinese_name||n.official_name}}（{{n.id.slice(0,8)}}）</option></select><select v-model="relationType" aria-label="关系类型"><option value="TRANSMISSION">产业链传导候选</option><option value="MACRO_SENSITIVITY">宏观敏感性候选</option><option value="SUPPLIER">供应商</option><option value="CUSTOMER">客户</option><option value="INDUSTRY">所属行业</option><option value="ISSUER">发行主体</option></select></div><input v-model="linkEvidence" placeholder="已有真实证据 ID（可选）"><textarea v-model="reason" placeholder="关系依据与未确认事项（至少10字）"/><button :disabled="busy||!subject||!object" @click="action('/research/relations/create',{subjectId:subject,objectId:object,type:relationType,evidenceId:linkEvidence||null,explanation:reason})">保存待审核关系</button><template v-if="relationTarget"><p>当前待审核关系 {{relationTarget}}</p><textarea v-model="quote" placeholder="关系核实所依据的官方原文摘录（至少10字）"/><div class="filters"><button v-for="[decision,label] in [['VERIFIED','核实当前关系'],['CONFLICT','记录关系冲突'],['REJECTED','否决当前关系'],['EXPIRED','标记关系失效']]" :key="decision" :disabled="busy" @click="action('/research/review',{target:'RELATION',id:relationTarget,decision,evidenceId:linkEvidence||null,reason,quote})">{{label}}</button></div><p>审核记录保留证据与真实披露时间；事件历史详情仅显示当时已经披露且有效的已核实关系。</p></template></template>
 </template></template>
 <section v-if="proof" ref="proofSection" class="research-detail"><h2>关联证据详情</h2><p>{{sourceName(proof.source_id,proof.source_name)}} · 来源等级 {{proof.level}} · {{proof.hash_valid?'实际字节哈希一致':'哈希不一致，禁止用于核实'}}</p><p>发布时间 <time :title="'UTC原值：'+utc(proof.published_at)">{{time(proof.published_at,'官方发布时间未知')}}</time> · 采集 <time :title="'UTC原值：'+utc(proof.collected_at)">{{time(proof.collected_at)}}</time> · 版本 {{proof.revision}}</p><code>SHA-256 {{proof.raw_content_hash}}</code><a v-if="safeOfficialUrl(proof.source_url)" :href="proof.source_url" target="_blank" rel="noopener noreferrer">查看证据原始来源 ↗</a><button @click="proof=undefined">关闭关联证据</button></section>
 <section v-if="detail" ref="detailSection" class="research-detail"><div class="section-title"><h2>事件详情与证据</h2><button @click="detail=undefined">关闭研究详情</button></div><h3>{{displayTitle(detail.event).text}}</h3><p class="muted">{{displayTitle(detail.event).status}}</p><details><summary>查看官方原文标题</summary><p>{{detail.event.original_title}}</p></details><p>来源等级 {{detail.event.level}} · 发布时间 <time :title="'UTC原值：'+utc(detail.event.published_at)">{{time(detail.event.published_at,'官方发布时间未知')}}</time> · 采集 <time :title="'UTC原值：'+utc(detail.event.collected_at)">{{time(detail.event.collected_at)}}</time></p><p>原始 URL：{{detail.event.source_url}}</p><code>SHA-256 {{detail.event.raw_content_hash}}</code><p>规则版本 {{detail.event.rule_version}} · {{detail.event.cluster_basis}}</p><details><summary>研究优先级依据</summary><pre>{{json(detail.event.score_basis)}}</pre></details><h3>证据修订记录</h3><p v-for="v in detail.versions||[]" :key="v.id">版本 {{v.revision}} · 采集 <time :title="'UTC原值：'+utc(v.collected_at)">{{time(v.collected_at)}}</time> <button @click="showProof(v.id)">查看版本证据</button></p><h3>关联实体</h3><p v-if="!detail.entities.length">尚无具备证据的实体识别结果</p><p v-for="n in detail.entities" :key="n.id">{{n.chinese_name||n.official_name}} · {{n.match_basis}}</p><h3>事实与研究推断</h3><p>原始消息以上述证据为准。中文摘要：尚未生成。正面和反面影响假设：尚无可溯源研究产物。</p><p v-for="u in detail.uncertainty" :key="u" class="muted">{{u}}</p><AiAnalysis :token="token" :event-id="detail.event.id"/><h3>补充官方证据与审核</h3><p v-for="e in detail.official_evidence" :key="e.evidence_id">{{e.evidence_id}} · {{state(e.status)}} · {{e.reason}}</p><input v-model="linkEvidence" placeholder="数据库中已有的官方证据 ID"><textarea v-model="reason" placeholder="同一事实或关系的审核依据（至少10字）"/><textarea v-model="quote" placeholder="官方证据中的真实原文摘录（核实时必填）"/><button :disabled="busy||!linkEvidence" @click="action('/research/official-evidence',{eventId:detail.event.id,evidenceId:linkEvidence,reason})">关联官方证据（保持待审核）</button><div class="filters"><button v-for="[code,label] in [['VERIFIED','确认已核实'],['CONFLICT','标记证据冲突'],['REJECTED','否决候选']]" :key="code" :disabled="busy" @click="action('/research/review',{target:relationTarget?'RELATION':'EVENT',id:relationTarget||detail.event.id,decision:code,evidenceId:linkEvidence||null,reason,quote})">{{label}}</button></div><p>已核实结论需要人工核对同一事实、有效官方证据及原文摘录；审核不会改变原始证据等级。</p><h3>审核日志</h3><p v-if="!detail.reviews.length">尚无人工审核记录</p><p v-for="r in detail.reviews" :key="r.id"><time :title="'UTC原值：'+utc(r.created_at)">{{time(r.created_at)}}</time> · {{state(r.decision)}} · {{r.reason}}</p></section>
</section>
</template>
<style scoped>
.macro-chart{width:100%;max-height:310px;background:#101b29;margin:18px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}textarea{display:block;width:100%;min-height:70px;background:#111f30;color:#dbe4ef;border:1px solid #324258;border-radius:6px;margin:10px 0;padding:12px}.research-detail{border-top:1px solid #405370;margin-top:22px;padding-top:20px}.research input{max-width:100%}.research select{max-width:100%}.research code{overflow-wrap:anywhere}.research p{overflow-wrap:anywhere}
</style>


